const CHAVE="ong-mao-solidaria:cadastros";export function obterCadastros(){const o=localStorage.getItem(CHAVE);if(!o)return[];try{const r=JSON.parse(o);return Array.isArray(r)?r:[]}catch{return console.warn("Não foi possível ler os cadastros salvos; ignorando dado corrompido."),[]}}function salvarCadastros(o){localStorage.setItem(CHAVE,JSON.stringify(o))}export function adicionarCadastro(o){const r=obterCadastros();return r.push({...o,id:Date.now(),dataCadastro:(new Date).toISOString()}),salvarCadastros(r),r}export function removerCadastro(o){const r=obterCadastros().filter(r=>r.id!==o);return salvarCadastros(r),r}